383	<body>
384	  <main>
385	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
386	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
387	        <circle cx="200" cy="200" r="200"/>
388	      </svg>
389	    </button>
390	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
391	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
392	    <div class="controls" role="group" aria-label="Circle controls">
393	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
394	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
395	    </div>
396	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
397	  </main>
398	
399	  <script defer>
400	    const CONFIG = {
401	      storageKey: 'circle-state',
402	      tapDelay: 300,
403	      colorShiftDuration: 500,
404	      colorModes: [
405	        { class: 'default', name: 'Default White' },
406	        { class: 'color-mode-1', name: 'Pink' },
407	        { class: 'color-mode-2', name: 'Teal' },
408	        { class: 'color-mode-3', name: 'Mint' }
409	      ],
410	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
411	      pulseInterval: 2500
412	    };
413	
414	    const el = {
415	      circle: document.getElementById('decorative-circle'),
416	      hint: document.getElementById('hint-text'),
417	      modeIndicator: document.getElementById('mode-indicator'),
418	      cycleBtn: document.getElementById('cycle-btn'),
419	      resetBtn: document.getElementById('reset-btn')
420	    };
421	
422	    let state = { active: false, colorMode: 0 };
423	    let tapCount = 0;
424	    let tapTimeout = null;
425	    let animatingColorShift = false;
426	
427	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
428	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
429	
430	    const storage = {
431	      save() {
432	        try {
433	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
434	        } catch {
435	          // Silently fail if localStorage is unavailable or quota exceeded
436	        }
437	      },
438	      load() {
439	        try {
440	          const saved = localStorage.getItem(CONFIG.storageKey);
441	          if (saved) {
442	            const parsed = JSON.parse(saved);
443	            if (parsed && typeof parsed === 'object') {
444	              state = { ...state, ...parsed };
445	            }
446	          }
447	        } catch {
448	          // Silently fail if parsing fails
449	        }
450	      }
451	    };
452	
453	    const updateClasses = () => {
454	      const colorClasses = CONFIG.colorModes.map(m => m.class);
455	      el.circle.classList.remove('active', ...colorClasses);
456	      el.circle.setAttribute('aria-pressed', state.active);
457	      if (state.active) el.circle.classList.add('active');
458	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
459	    };
460	
461	    const updateUI = () => {
462	      let hintText = state.active ? '✓ Active • ' : '';
463	
464	      if (CONFIG.isTouch) {
465	        hintText += state.active ? 'Tap to cycle colors' : 'Tap once to activate, twice to change color';
466	      } else {
467	        hintText += state.active ? 'Double-click to cycle • Press C or use button' : 'Double-click to change color • Press C or use button';
468	      }
469	
470	      el.hint.textContent = hintText;
471	
472	      const showMode = state.active && state.colorMode > 0;
473	      el.modeIndicator.classList.toggle('visible', showMode);
474	      if (showMode) {
475	        const modeName = getColorModeName(state.colorMode);
476	        el.modeIndicator.textContent = `◆ ${modeName.toUpperCase()} MODE`;
477	      }
478	    };
479	
480	    const applyState = () => {
481	      updateClasses();
482	      updateUI();
483	    };
484	
485	    const toggleActive = () => {
486	      state.active = !state.active;
487	      applyState();
488	      storage.save();
489	    };
490	
491	    const cycleColor = () => {
492	      if (animatingColorShift) return;
493	      animatingColorShift = true;
494	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
495	      state.active = true;
496	      el.circle.classList.add('color-shifting');
497	      setTimeout(() => {
498	        el.circle.classList.remove('color-shifting');
499	        animatingColorShift = false;
500	      }, CONFIG.colorShiftDuration);
501	      applyState();
502	      storage.save();
503	    };
504	
505	    const resetState = () => {
506	      state = { active: false, colorMode: 0 };
507	      applyState();
508	      storage.save();
509	    };
510	
511	    const handleDblClick = (e) => {
512	      e.preventDefault();
513	      if (!state.active) {
514	        state.active = true;
515	        applyState();
516	      }
517	      cycleColor();
518	    };
519	
520	    const handleTouchEnd = () => {
521	      tapCount++;
522	      clearTimeout(tapTimeout);
523	      if (tapCount === 1) {
524	        tapTimeout = setTimeout(() => {
525	          if (tapCount === 1) toggleActive();
526	          tapCount = 0;
527	        }, CONFIG.tapDelay);
528	      } else if (tapCount === 2) {
529	        cycleColor();
530	        tapCount = 0;
531	      }
532	    };
533	
534	    const keyHandlers = {
535	      ' ': toggleActive,
536	      'enter': toggleActive,
537	      'c': cycleColor,
538	      'r': resetState
539	    };
540	
541	    const handleKeyDown = (e) => {
542	      const handler = keyHandlers[e.key.toLowerCase()];
543	      if (handler) {
544	        e.preventDefault();
545	        handler();
546	      }
547	    };
548	
549	    const initListeners = () => {
550	      el.circle.addEventListener('click', toggleActive);
551	      el.circle.addEventListener('dblclick', handleDblClick);
552	      el.circle.addEventListener('touchend', handleTouchEnd);
553	      el.circle.addEventListener('blur', () => {
554	        tapCount = 0;
555	        clearTimeout(tapTimeout);
556	      });
557	      document.addEventListener('keydown', handleKeyDown);
558	      el.cycleBtn.addEventListener('click', cycleColor);
559	      el.resetBtn.addEventListener('click', resetState);
560	    };
561	
562	    const initApp = () => {
563	      storage.load();
564	      applyState();
565	      initListeners();
566	      el.circle.focus();
567	    };
568	
569	    if (document.readyState === 'loading') {
570	      document.addEventListener('DOMContentLoaded', initApp);
571	    } else {
572	      initApp();
573	    }
574	  </script>
575	</body>
576	</html>
